head.script:
scwin.add = function(x, y, width, height) {
	widgetContainer1.addWidgets({
		title: "widget" + scwin.wcount,
		src: "/sample/common_link/widgetContainer_WPF-1472_(WSQ-2377)_sub.xml",
		scope: true,
		x: x,
		y: y,
		unitWidth: width,
		unitHeight: height,
		params: "USER_DATA",
		hasTitleBar: !(scwin.wcount % 2),
		fixed: !!(scwin.wcount % 2)
	});
	scwin.wcount++;
};

scwin.onpageload2 = function() {
	scwin.wcount = 0;
	scwin.add(0, 0, 2, 2);
	scwin.add(4, 0, 3, 3);
};
